def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_reqs = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if budget <= 0:
        return 0.0

    total_players = 1 + len(alive_opponents)
    total_req = WATER_REQ
    for r in opp_reqs:
        total_req += r

    scarcity_ratio = 1.0
    if total_req > 0:
        scarcity_ratio = float(supply) / float(total_req)

    severe_need = (hp <= 3) or (no_water_days >= 1)
    moderate_need = (hp <= 5)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0

    units_available = float(supply) / float(WATER_REQ)
    contested = units_available < float(total_players)
    very_tight = scarcity_ratio < 0.34
    loose = scarcity_ratio > 0.5

    if not alive_opponents:
        if severe_need:
            bid = 42.0
        elif moderate_need:
            bid = 28.0
        else:
            bid = 18.0
        return max(0.0, min(float(budget), bid))

    if severe_need:
        if prev_bids:
            bid = max(84.0, highest_prev + 2.25)
        else:
            bid = 82.0
        if very_tight:
            bid += 8.0
    elif very_tight or contested:
        anchor = max(avg_prev, highest_prev - 1.0)
        bid = max(68.0, anchor + 1.75)
        if hp <= 4:
            bid += 4.0
    elif loose:
        if highest_prev >= 85.0 and hp > 4:
            bid = 24.0
        else:
            bid = 46.0 if moderate_need else 34.0
    else:
        if prev_bids:
            bid = max(52.0, min(76.0, avg_prev - 3.0))
        else:
            bid = 50.0

    if day >= 8:
        bid += 4.0 if severe_need else 1.5

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left > 1 and not severe_need:
        reserve_floor = min(float(budget) * 0.35, 70.0)

    max_spend = float(budget) - reserve_floor
    if severe_need:
        max_spend = float(budget)
    if max_spend < 0.0:
        max_spend = 0.0

    bid = min(bid, max_spend)
    bid = min(bid, float(budget))
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.55))

    # Estimate opponent pressure from yesterday's bids
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If an opponent bid very high yesterday, they likely were pressured and will bid again.
    # Use a slightly higher offer than their observed peak, but cap by budget.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Supply pressure: closer to minimum supply implies more competition.
    supply_tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_tightness = max(0.0, min(1.0, supply_tightness))

    # Base bid target
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Strong pressure: be competitive
        target = max(highest_prev_bid + 2.0, DAILY_SALARY * (0.35 + 0.35 * supply_tightness))
        if hp <= 2.0:
            target = max(target, DAILY_SALARY * 0.85)
    else:
        # Moderate pressure: slightly above typical survival bids
        target = max(DAILY_SALARY * (0.50 + 0.25 * supply_tightness), highest_prev_bid * 0.95 + 1.0)
        if hp <= 2.0:
            target = max(target, DAILY_SALARY * 0.75)

    # Ensure we don't overspend when supply is ample
    if supply >= 21.0:
        target *= 0.92

    # Final cap by budget and reasonable upper bound
    max_reasonable = min(budget, DAILY_SALARY * (1.05 + 0.15 * supply_tightness))
    bid = min(max_reasonable, target)

    # Never bid negative or zero when we can afford something meaningful
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)
